def suffixed_err(src: str, pos: Pos, msg: str) -> TOMLDecodeError:
    """Return a `TOMLDecodeError` where error message is suffixed with
    coordinates in source."""

    def get_coordinates(src: str, pos: Pos) -> tuple[int, int]:
        if pos >= len(src):
            # For EOF errors, use the last position
            line = src.count("\n") + 1
            if line == 1:
                column = len(src) + 1
            else:
                column = len(src) - src.rindex("\n")
            return line, column

        line = src.count("\n", 0, pos) + 1
        if line == 1:
            column = pos + 1
        else:
            column = pos - src.rindex("\n", 0, pos)
        return line, column

    lineno, colno = get_coordinates(src, pos)
    coord_str = f"line {lineno}, column {colno}"

    error_msg = f"{msg} (at {coord_str})"
    return TOMLDecodeError(error_msg, doc=src, pos=pos, lineno=lineno, colno=colno)

